import { countsClaimed, countsLive, hasTag, isOpen, useClaims, useTags } from '../claims/useClaims';
import { isOverdue } from '../claims/overdue';
import { useGrace } from '../claims/useGrace';
import { isReviewLate } from '../claims/reviewLate';
import { isPendingLate } from '../claims/pendingLate';
import { capped, claimDue, dueTotal, excess, formatCents, roundsHalfUp, toCents } from '../rates/due';
import { claimRate, rateOn, useRates } from '../rates/useRates';
import { useCap, useFloor, useLatePct, usePolicy, useSettings } from '../settings/useSettings';
import { usePools } from '../pools/usePools';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, retiredOn, usePeople, type Person } from './usePeople';

export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

// The figures the people list, its totals, the summary and the header are all worked from, so
// every place that repeats a figure shows the same one.
export function useSheetFigures(sheet: string) {
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const tags = useTags(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const grace = useGrace(sheet);
  const late = { pct: useLatePct(sheet), today, grace };
  const policy = usePolicy(sheet);
  const cap = useCap(sheet);
  const pools = usePools(sheet);
  const settings = useSettings(sheet);
  const reviewSla = settings?.reviewSla;
  const pendingSla = settings?.pendingSla;
  const byId = new Map(people.map((p) => [p.id, p]));
  const live = claims.filter((c) => {
    const person = byId.get(c.personId);
    return person !== undefined && countsLive(c, retiredOn(person, today), today);
  });
  // The claims that count toward claimed: a held claim does, as it does in every total.
  const claimedLive = claims.filter((c) => {
    const person = byId.get(c.personId);
    return person !== undefined && countsClaimed(c, retiredOn(person, today), today);
  });
  // A shared claim's parts: each holder's part is the claim's amount times their share over 100, times the rate of the
  // holder's own grade in force on the claim's date over 100, rounded like the claim (0.00 when that grade has no rate);
  // a settled claim's parts stay frozen at its settled due times the share over 100, rounded half to even. Each part is
  // taken from the claim's own person; only a counting claim with a figure has parts.
  const parts = live.flatMap((c) => {
    const owner = byId.get(c.personId)!;
    const due = (c.shares ?? []).length === 0 ? null : claimDue(c, claimRate(rates, gradeOn(owner, c.date), c), floor, late, policy);
    if (due === null) return [];
    const frozen = c.status === 'SETTLED' && c.due !== '';
    return (c.shares ?? [])
      .filter((h) => byId.has(h.personId))
      .flatMap((h) => {
        if (frozen) return [{ claim: c, ownerId: c.personId, holderId: h.personId, part: halfEvenDiv(due * toCents(h.share), 10000n) }];
        const rate = claimRate(rates, gradeOn(byId.get(h.personId)!, c.date), c);
        // A holder whose grade has no rate holds 0.00: it takes nothing and gives them no figure.
        if (rate === undefined) return [];
        const part = roundDiv(toCents(c.amount) * toCents(h.share) * toCents(rate), 100000000n, roundsHalfUp(c, policy));
        return [{ claim: c, ownerId: c.personId, holderId: h.personId, part }];
      });
  });
  // What a person's parts move: added for the parts they hold, taken off for the parts of their own claims.
  const partsOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    parts.reduce(
      (sum, p) => (!which(p.claim) ? sum : sum + (p.holderId === person.id ? p.part : 0n) - (p.ownerId === person.id ? p.part : 0n)),
      0n,
    );
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  // The sum of a person's figures, before the cap, with their parts; holding a part is a figure.
  const uncappedOf = (person: Person) => {
    const own = dueTotal(
      live.filter((c) => c.personId === person.id),
      (c) => claimRate(rates, gradeOn(person, c.date), c),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
      policy,
    );
    if (own === null && !parts.some((p) => p.holderId === person.id)) return null;
    return (own ?? 0n) + partsOf(person, () => true);
  };
  // A person's cut total: their cuts in every pool added up.
  const cutOf = (personId: string) =>
    pools.reduce(
      (sum, pool) => pool.members.reduce((s, m) => (m.personId === personId && m.cut !== '' ? s + toCents(m.cut) : s), sum),
      0n,
    );
  // A person's due-total: at most their cap less their cut total, not below 0.00 (n/a is not capped);
  // everything that adds up due-totals uses it. Their excess is how far the sum of their figures is above that.
  // The cap is the one in force on the date of their latest claim that counts (the sheet's today when none does).
  const capOf = (person: Person) => {
    const latest = live.filter((c) => c.personId === person.id).reduce<string | undefined>((d, c) => (d === undefined || c.date > d ? c.date : d), undefined);
    const on = latest ?? today;
    return on === undefined ? '' : cap(on);
  };
  const totalOf = (person: Person) => capped(uncappedOf(person), capOf(person), cutOf(person.id));
  const excessOf = (person: Person) => excess(uncappedOf(person), capOf(person), cutOf(person.id));
  // A person's settled-total and open-total: the dues of their counting SETTLED claims (frozen
  // figures, corrections included), and of their counting OPEN and PENDING claims; n/a adds nothing.
  // Together they make the sum of their figures before the cap.
  const dueSumOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    live
      .filter((c) => c.personId === person.id && which(c))
      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
  // Each counts the person's parts of those claims the same way.
  const settledOf = (c: (typeof live)[number]) => c.status === 'SETTLED';
  const settledTotalOf = (person: Person) => dueSumOf(person, settledOf) + partsOf(person, settledOf);
  const openTotalOf = (person: Person) => dueSumOf(person, isOpen) + partsOf(person, isOpen);
  // Each person's settled-total, open-total and cut total (always a figure), in list order.
  const settledFigures = people.map(settledTotalOf);
  const openFigures = people.map(openTotalOf);
  const cutFigures = people.map((p) => cutOf(p.id));
  // The sheet's settled-total, open-total and cut total: everyone's figure added up, trimmed.
  const sheetSettledTotal = formatCents(trimmedSum(settledFigures));
  const sheetOpenTotal = formatCents(trimmedSum(openFigures));
